strings.text:
/* Module 2: midnight blue, turquoise signal lines, warm champagne accents. */
.ml-root{--gold:#79e0d2;--bronze:#61b9c7;--text:#f0f6fa;--muted:#bacbd8;--line:#6095b84d;background:radial-gradient(ellipse at 5% 0%,#215c6e55,transparent 55%),radial-gradient(ellipse at 100% 100%,#343b7755,transparent 50%),#081322}
.ml-head,.ml-body{border-color:#42668588;background:linear-gradient(145deg,#1a3045,#101d30 65%,#182640);box-shadow:0 16px 42px #0004,inset 0 1px #b9dcf61a}
.ml-head{border-radius:12px}.ml-title{color:#e7d3ad}.ml-body{scrollbar-color:#61b9c7 #101d30}
.ml-progress i.on{background:linear-gradient(90deg,#80e4d2,#73b9ef);box-shadow:0 0 8px #79e0d233}
.ml-button.primary{color:#08212c;border-color:#79e0d2;background:linear-gradient(120deg,#9debd9,#78bce7)}
.ml-button.primary:hover:not(:disabled){background:#b6f2e2}
.ml-theory-flow{background:linear-gradient(110deg,#1b3948,#12243d);border-color:var(--line)}
.ml-theory-step{border-color:#66bdcc66;background:#1a334b}.ml-theory-example{background:#51bfc51b}
.ml-theory-face{border-color:#658eaf;background:#192d45}.ml-theory-face.back{background:#153c35}
.ml-vocab-face{background:#1a3048}.ml-vocab-face.back{background:#133c44}.ml-theory-controls button{background:#12243d;border-color:var(--line);min-height:44px}
.ml-card.reveal.open,.ml-bubble.right{background:#4bb9bb1f;border-color:#79e0d280}.ml-token{background:#21384e;color:#f0f6fa;min-height:44px}
.ml-option:disabled.good{opacity:1}.ml-result{background:radial-gradient(circle at 20% 50%,#328d9633,transparent 48%),#122239}.ml-ring:before{background:#122239}
.ml-confetti i:nth-child(3n){background:#e7d3ad}.ml-confetti i:nth-child(3n+1){background:#79b7ef}
.ml-bubble{max-width:94%}.ml-phrase .ml-rate button{min-height:44px}.ml-slide{animation-name:m2-slide-in}
@keyframes m2-slide-in{from{opacity:0;transform:translate3d(0,18px,-35px) rotateX(3deg)}to{opacity:1;transform:none}}
.m2-scene{position:relative;isolation:isolate;min-height:180px;overflow:hidden;border:1px solid #79e0d255;border-radius:16px;background:linear-gradient(#90d6ef08 1px,transparent 1px),linear-gradient(90deg,#90d6ef08 1px,transparent 1px),radial-gradient(ellipse at center,#235062,#0c1a2d);background-size:24px 24px,24px 24px,auto}
.m2-network{position:absolute;inset:20px 20px 50px;display:flex;align-items:center;gap:8px}
.m2-endpoint{padding:8px 10px;border:1px solid #8de9d86b;border-radius:8px;background:#0c2237;color:#a7ebdf;font-size:10px;letter-spacing:.06em;z-index:1}
.m2-wire{position:relative;height:2px;flex:1;background:linear-gradient(90deg,#79e0d255,#7aa9e8,#79e0d255)}
.m2-wire i{position:absolute;top:-4px;left:0;width:10px;height:10px;border-radius:3px;background:#99f5df;box-shadow:0 0 12px #79e0d2;animation:m2-packet 5s linear infinite}.m2-wire i:nth-child(2){animation-delay:-1.65s}.m2-wire i:nth-child(3){animation-delay:-3.3s}
@keyframes m2-packet{0%{left:0;opacity:0;transform:scale(.6)}10%,85%{opacity:1}100%{left:calc(100% - 10px);opacity:0;transform:scale(1)}}
.m2-perspective{position:absolute;left:calc(50% - 57px);top:27px;width:114px;height:84px;perspective:700px}
.m2-device{position:relative;width:114px;height:84px;transform-style:preserve-3d;animation:m2-device-float 7s ease-in-out infinite}
.m2-device-front,.m2-device-back{position:absolute;inset:0;border:1px solid #9debd9;border-radius:10px;background:linear-gradient(135deg,#284b62,#102436);backface-visibility:hidden}
.m2-device-front{display:grid;place-items:center;transform:translateZ(9px);box-shadow:0 12px 24px #0006}.m2-device-front svg{width:72px;height:56px;color:#a4eddc}
.m2-device-back{transform:rotateY(180deg) translateZ(9px)}.m2-device-side{position:absolute;right:-9px;top:5px;width:18px;height:74px;background:#365c76;transform:rotateY(90deg)}
@keyframes m2-device-float{0%,100%{transform:rotateY(-18deg) rotateX(9deg) translateY(2px)}50%{transform:rotateY(18deg) rotateX(-6deg) translateY(-5px)}}
.m2-scene-caption{position:absolute;bottom:15px;left:16px;max-width:55%;color:#c2d9e7;font-size:11px}
.m2-motion{position:absolute;right:10px;bottom:8px;min-height:36px;border:1px solid #79e0d255;border-radius:7px;background:#0c2035;color:#c2e7e7;padding:6px 8px;font-size:10px!important}
.m2-scene.paused *{animation-play-state:paused!important}
.m2-hook{display:grid;gap:14px;padding:20px;border-left:3px solid #e7d3ad;border-radius:0 12px 12px 0;background:linear-gradient(90deg,#79e0d211,transparent)}
.m2-tag{color:#79e0d2;font-size:10px;font-weight:800;letter-spacing:.12em}
.m2-hook-message{font-size:clamp(22px,3vw,34px);font-weight:750;color:#e7d3ad}
.m2-source{display:grid;gap:8px;border:1px solid var(--line);border-radius:12px;padding:14px;background:#0b1b2c}.m2-source p{font-size:15px;line-height:1.5}
.m2-details{display:grid;gap:12px}.m2-details>.ml-button{justify-self:end}.m2-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}
.m2-fields label{display:grid;gap:6px;font-size:13px;color:#bacbd8}.m2-fields input{width:100%;min-width:0;min-height:44px;padding:10px;border:1px solid #638cab;border-radius:8px;background:#0b192c;color:#f0f6fa;font:inherit}
.m2-fields input:focus-visible{outline:2px solid #79e0d2;outline-offset:2px}.m2-fields input.good{border-color:#68ab7e}.m2-fields input.bad{border-color:#ffaaa7}.m2-fields small{font-size:11px;color:#ffaaa7}.m2-fields small.m2-correct{color:#9cddb5}
.ml-theory-flip,.ml-theory-flip-inner{min-height:100px}.ml-theory-face{overflow-wrap:anywhere}.ml-vocab-card,.ml-vocab-inner{min-height:108px}
@media(max-width:650px){.m2-scene{min-height:165px}.m2-endpoint{font-size:8px;padding:7px}.m2-network{inset-inline:9px}.m2-perspective{transform:scale(.85);transform-origin:center}.m2-hook{padding:14px;gap:10px}.m2-fields{grid-template-columns:1fr}.m2-scene-caption{font-size:10px;max-width:44%}.m2-motion{max-width:50%;min-height:44px}.ml-theory-flip,.ml-theory-flip-inner{min-height:132px}.ml-vocab-card,.ml-vocab-inner{min-height:112px}.ml-foot{flex-wrap:wrap}.ml-note{display:none}}
@media(prefers-reduced-motion:reduce){.m2-device,.m2-wire i{animation:none!important}.m2-device{transform:rotateY(-12deg) rotateX(6deg)}.m2-wire i{left:22%}.m2-wire i:nth-child(2){left:50%}.m2-wire i:nth-child(3){left:78%}.m2-motion{display:none}}
/* Fit the lesson iframe below the platform header on laptop/zoomed desktops.
   Keep overflow available for smaller/mobile screens; never crop lesson content. */
@media(min-width:900px){
  .ml-slide[data-kind="mission"] .ml-options{grid-template-columns:repeat(2,minmax(0,1fr))}
  .m2-fields{grid-template-columns:repeat(3,minmax(0,1fr))}
}
@media(min-width:900px) and (max-height:760px){
  .ml-body{padding:12px}.ml-slide{gap:8px}.ml-title{font-size:32px}
  .ml-theory{gap:6px}.ml-theory-rule{min-height:0;font-size:15px}
  .ml-theory-flow{min-height:64px;padding:6px}.ml-theory-step{padding:6px 8px}.ml-theory-step strong{font-size:16px}
  .ml-theory-points p{min-height:44px;padding:7px 9px}.ml-theory-example{padding:8px 10px}
  .ml-theory-flip,.ml-theory-flip-inner{min-height:84px}
  .m2-scene{min-height:140px}.m2-hook{padding:12px;gap:8px}.m2-hook-message{font-size:26px}
  .ml-slide[data-kind="mission"] .m2-scene{min-height:96px}
  .ml-slide[data-kind="mission"] .m2-perspective{top:0;transform:scale(.7);transform-origin:top center}
  .ml-slide[data-kind="mission"] .m2-network{inset:8px 20px 38px}
}

