/* Fit desktop lesson content below the platform header without hiding overflow.
   Small/mobile screens retain scrolling and the existing navigation. */
@media(min-width:900px){
  .ml-slide[data-kind="mission"] .ml-options{grid-template-columns:repeat(2,minmax(0,1fr))}
  .m3-fields{grid-template-columns:repeat(3,minmax(0,1fr))}
