  .m3-document[data-dense="true"] dl{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}
  .m3-document[data-dense="true"] dl>div{grid-template-columns:1fr;gap:3px;padding:8px 12px}
  .m3-document[data-dense="true"] dl>div:nth-child(odd){border-right:1px solid #b7a2d21a}
}
@media(min-width:900px) and (max-height:760px){
