  .m3-perspective{width:80px;height:60px}.m3-dossier{scale:.48;transform-origin:top left}
  .m3-process{gap:4px}.m3-stages>div{display:flex;align-items:center;padding:3px 6px;gap:6px}.m3-stages b{font-size:13px}
  .ml-slide[data-kind="mission"]{gap:5px}.ml-slide[data-kind="mission"] .ml-sub{font-size:15px}.ml-slide[data-kind="mission"] .ml-lead{font-size:17px}
  .m3-hook{padding:12px;gap:8px}.m3-hook-message{font-size:26px}
  .m3-document-reader{gap:8px}.m3-document header{padding:8px 12px;gap:4px}
  .m3-document dl>div{padding:6px 12px;gap:10px}.m3-document dd{font-size:13px;line-height:1.4}
